insert into churn_reasons (title, category, description, evidence_source, affected_segment, flywheel_driver, flywheel_subdriver, is_example) values ('Orders arrive late or cold', 'delivery experience', 'Late and cold-food deliveries are a top driver of customers stopping ordering, especially at peak times when courier supply is tight.', 'Example entry — replace with your real evidence source', 'Peak-time orderers and suburban zones with longer courier travel times', 'Delivery', 'Absolute delivery time', true);
insert into churn_reasons (title, category, description, evidence_source, affected_segment, flywheel_driver, flywheel_subdriver, is_example) values ('The app feels slow and hard to use', 'app & tech', 'Customers on older or low-end devices experience long startup and search times, and abandon before completing their first order.', 'Example entry — replace with your real evidence source', 'Customers on low-end Android devices', 'App experience', 'Usability', true);
insert into hypotheses (churn_reason_id, title, if_we, then_outcome, because_mechanism, target_segment, primary_metric, success_criterion, status, is_example) values (1, 'Live courier ETA map during order tracking', 'If we show a live map with the courier position and a dynamic ETA during order tracking', 'then contact rate per 1,000 late orders will decrease by at least 15% within 8 weeks', 'uncertainty about when food will arrive, rather than the delay itself, drives cancellation and support contact — visible progress reduces that uncertainty', 'Orders running more than 10 minutes past the original ETA', 'Support contact rate per 1,000 late orders', '-15% contact rate on late orders vs. baseline within 8 weeks', 'accepted', true);
insert into impact_sizings (hypothesis_id, affected_customers, expected_lift, revenue_at_stake, confidence, assumptions, method) values (1, 'Late orders are about 6% of weekly volume, pilot scope 1.1m orders per quarter', '-15% contact rate is roughly 9k fewer support contacts per quarter', 'Support cost of about 3.5 per contact, roughly 32k saved per quarter plus retention halo', 'medium', 'Assumes the courier location feed covers 95% of couriers. Example figures.', 'Contact-rate baseline from support tickets linked to late orders (example)');
insert into technical_necessities (hypothesis_id, requirement_type, description, effort, dependencies, owning_team) values (1, 'engineering', 'Real-time courier location stream into the tracking screen', 'L', 'Courier app location permissions', 'Logistics platform');
insert into technical_necessities (hypothesis_id, requirement_type, description, effort, dependencies, owning_team) values (1, 'data', 'Late-order classifier feed to trigger the pilot', 'S', '', 'Customer analytics');
insert into hypotheses (churn_reason_id, title, if_we, then_outcome, because_mechanism, target_segment, primary_metric, success_criterion, status, is_example) values (2, 'Cut app startup time below two seconds on low-end devices', 'If we reduce app startup time on low-end Android devices to under two seconds', 'then 7-day retention for new installs on those devices will increase by at least 3 percentage points within 8 weeks', 'a slow first launch causes customers to abandon before their first search, so the app never gets a chance to show its value', 'New installs on low-end Android devices', '7-day retention of new installs', '+3 percentage points 7-day retention vs. baseline within 8 weeks', 'submitted', true);
insert into impact_sizings (hypothesis_id, affected_customers, expected_lift, revenue_at_stake, confidence, assumptions, method) values (2, 'About 15% of new installs come from low-end Android devices', '+3pct retention is roughly 4.5k retained users per month', 'To be sized by the Mobile platform team', 'low', 'Assumes startup time is measurable per device tier. Example figures.', 'Device-tier segmentation of install cohorts (example)');
insert into technical_necessities (hypothesis_id, requirement_type, description, effort, dependencies, owning_team) values (2, 'engineering', 'App startup profiling and lazy-loading of non-critical modules', 'M', '', 'Mobile platform');
